// Set window._sheetianImportBytes to the bytes generated by import-fixture.mjs,
// then run through Obsidian CLI eval. Only isolated test files are removed.
(async()=>{
  const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
  const assert=(ok,message)=>{if(!ok)throw new Error(message);};
  const bytes=window._sheetianImportBytes;
  assert(bytes?.byteLength,'Provide the XLSX test fixture bytes first');
  const prior=app.workspace.activeLeaf,root=`Sheetian import checks ${Date.now()}`;
  const plugin=app.plugins.getPlugin('sheetian'),files=[],results=[];
  const find=file=>app.workspace.getLeavesOfType('spreadsheet-view').find(l=>l.view.file?.path===file.path);
  const file=await plugin.importWorkbook('Formula workbook.xlsx',bytes,root);files.push(file);
  let leaf=find(file),view=leaf.view;await delay(180);
  assert(app.commands.commands['sheetian:import-xlsx'],'Import command is not registered');
  const sheets=view.workbook.current.getAllSheets();
  assert(sheets.length===4,'Sheet tabs lost');
  assert(sheets[2].hide===1,'Hidden sheet became visible');
  assert(sheets[1].data[0][1].f==='=D1+1'&&sheets[1].data[0][1].v===5,'Uncached formula not calculated on its own sheet');
  assert(sheets[0].data[0][1].v===45379,'Calculating another tab overwrote the date cell');
  assert(sheets[0].config.merge['0_3'].cs===2&&sheets[0].frozen.type==='both','Merges or frozen panes lost');
  results.push('Import creates four tabs with formulas, styles, dates, merges, and uncached results intact');
  const edit=async(row,column,text)=>{
    view.workbook.current.setSelection([{row:[row,row],column:[column,column]}]);await delay(60);
    const area=view.contentEl.querySelector('.fortune-cell-area'),rect=area.getBoundingClientRect();
    area.dispatchEvent(new MouseEvent('dblclick',{clientX:rect.left+10,clientY:rect.top+10,button:0,bubbles:true}));await delay(60);
    const input=view.contentEl.querySelector('.luckysheet-cell-input');input.innerText=text;
    input.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',keyCode:13,which:13,bubbles:true}));await delay(150);
  };
  view.workbook.current.activateSheet({id:'xlsx-1'});await delay(80);
  await edit(0,0,'8');
  let summary=view.workbook.current.getSheet({id:'xlsx-2'});
  assert(summary.data[0][0].v===15,'SUM did not recalculate across tabs');
  assert(summary.data[1][0].v===16,'Absolute reference did not recalculate');
  assert(summary.data[1][1].v===16,'Shared formula did not recalculate');
  assert(summary.data[6][0].v===13,'Quoted sheet name reference did not recalculate');
  assert(summary.data[3][0].v===false&&summary.data[4][0].v===5,'Boolean/numeric formulas failed');
  results.push('Editing imported inputs recalculates ordinary, shared, absolute, boolean, and quoted cross-sheet formulas');
  await leaf.detach();await delay(100);
  const saved=JSON.parse(await app.vault.read(file));
  assert(saved[1].celldata.filter(c=>c.v?.f).length===10,'Formula text lost on save');
  assert(saved[1].calcChain.length===10,'Dependency chain lost on save');
  leaf=app.workspace.getLeaf(true);await leaf.openFile(file);app.workspace.setActiveLeaf(leaf,{focus:true});await delay(160);view=leaf.view;
  view.workbook.current.activateSheet({id:'xlsx-1'});await delay(80);await edit(1,0,'20');
  summary=view.workbook.current.getSheet({id:'xlsx-2'});
  assert(summary.data[0][0].v===28&&summary.data[2][1].v===40,'Formula dependency tracking failed after reopen');
  await leaf.detach();await delay(100);
  results.push('Formulas and dependency chains survive save, reopen, and subsequent edits');
  const firstContents=await app.vault.read(file);
  const again=await plugin.importWorkbook('Formula workbook.xlsx',bytes,root);files.push(again);
  assert(again.path===`${root}/Formula workbook-1.sheet`,'Import collision overwrote the first workbook');
  assert(await app.vault.read(file)===firstContents,'First import changed during repeated import');
  await find(again).detach();await delay(100);
  results.push('Repeated import creates a numbered file and preserves existing workbooks');
  let failed=false;
  try{await plugin.importWorkbook('invalid.xlsx',new Uint8Array([1,2,3]),root);}catch{failed=true;}
  assert(failed&&!app.vault.getAbstractFileByPath(`${root}/invalid.sheet`),'Invalid import created a workbook');
  results.push('Invalid input fails before creating a vault file');
  if(prior)app.workspace.setActiveLeaf(prior,{focus:true});
  for(const f of files)await app.vault.trash(f,true);
  await app.vault.trash(app.vault.getAbstractFileByPath(root),true);delete window._sheetianImportBytes;
  return JSON.stringify({passed:results.length,results});
})()
